import os
import time

import pytest

import tokens


@pytest.fixture
def tz(request):
    """Set TZ for the test, restore the previous TZ afterward."""
    old_tz = os.environ.get("TZ")
    old_time = time.time  # snapshot in case tests monkeypatch it
    os.environ["TZ"] = request.param
    time.tzset()
    yield
    if old_tz is None:
        os.environ.pop("TZ", None)
    else:
        os.environ["TZ"] = old_tz
    time.tzset()


@pytest.mark.parametrize("tz", ["America/Los_Angeles", "UTC", "Asia/Kolkata"], indirect=True)
def test_make_token_exp_is_utc_epoch(tz):
    exp = tokens.make_token({}, 3600)["exp"]
    assert abs(exp - (time.time() + 3600)) < 5


@pytest.mark.parametrize("tz", ["America/Los_Angeles", "UTC", "Asia/Kolkata"], indirect=True)
def test_is_valid_boundaries(tz, monkeypatch):
    token = {"exp": 1_000_000.0}
    monkeypatch.setattr(time, "time", lambda: 999_999.0)
    assert tokens.is_valid(token) is True
    monkeypatch.setattr(time, "time", lambda: 1_000_000.0)
    assert tokens.is_valid(token) is False
    monkeypatch.setattr(time, "time", lambda: 1_000_001.0)
    assert tokens.is_valid(token) is False

from datetime import datetime, timezone


def make_token(payload, lifetime_seconds):
    return {
        "payload": payload,
        "exp": datetime.now(timezone.utc).timestamp() + lifetime_seconds,
    }


def is_valid(token):
    return time.time() < token["exp"]


import time  # noqa: E402  (used by is_valid; kept at top-level import order simple)

